"""Provider-neutral, self-directed goal selection for AVA.

An injected proposer can generate novel goals without a fixed human task list.
This component freely selects and records intentions; it deliberately cannot execute
tools, make purchases, change permissions, or control physical actuators.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Callable, Protocol, Sequence


@dataclass(frozen=True)
class GoalProposal:
    """Untrusted candidate generated by a model or other goal proposer.

    Ratings are integer estimates from 0 (none) through 5 (highest).
    A proposal's own safety flags are *not* proof of authorization.
    """

    goal_id: str
    description: str
    expected_value: int
    feasibility: int
    learning_value: int
    external_effect: bool = False
    requires_new_access: bool = False
    estimated_spend_minor: int = 0

    def __post_init__(self) -> None:
        if not isinstance(self.goal_id, str) or not self.goal_id.strip():
            raise ValueError("goal_id is required")
        if not isinstance(self.description, str) or not self.description.strip():
            raise ValueError("description is required")
        for field in ("expected_value", "feasibility", "learning_value"):
            value = getattr(self, field)
            if type(value) is not int or not 0 <= value <= 5:
                raise ValueError(f"{field} must be an integer from 0 to 5")
        if type(self.estimated_spend_minor) is not int or self.estimated_spend_minor < 0:
            raise ValueError("estimated_spend_minor must be a non-negative integer")
        if type(self.external_effect) is not bool or type(self.requires_new_access) is not bool:
            raise ValueError("goal flags must be booleans")


@dataclass(frozen=True)
class GoalAssessment:
    proposal: GoalProposal
    eligible: bool
    reason: str
    score: int


@dataclass(frozen=True)
class GoalDecision:
    owner_id: str
    selected: GoalProposal | None
    assessments: tuple[GoalAssessment, ...]
    created_at: str


@dataclass(frozen=True)
class GoalOutcome:
    owner_id: str
    goal_id: str
    completed: bool
    evidence: str


class GoalProposer(Protocol):
    """A host-supplied model or algorithm that imagines possible new goals."""

    def __call__(self, history: Sequence[GoalOutcome]) -> Sequence[GoalProposal]: ...


class AutonomousGoalDirector:
    """Choose original goals across domains without a human-authored task list.

    The host authenticates the owner, chooses a goal proposer, and independently
    authorizes any resulting *actions*. Proposals are untrusted suggestions and
    cannot grant themselves capabilities. This director does not run actions.
    History is deliberately ephemeral; encrypted persistence is a host concern.
    """

    def __init__(self, *, owner_id: str, proposer: GoalProposer) -> None:
        if not isinstance(owner_id, str) or not owner_id.strip():
            raise ValueError("owner_id is required")
        if not callable(proposer):
            raise TypeError("proposer must be callable")
        self.owner_id = owner_id
        self._proposer = proposer
        self._outcomes: dict[str, GoalOutcome] = {}
        self._selected_id: str | None = None

    def history(self) -> tuple[GoalOutcome, ...]:
        return tuple(self._outcomes.values())

    def decide(self) -> GoalDecision:
        """Propose and select a goal, but perform no tool or external action."""
        proposals = tuple(self._proposer(self.history()))
        if not all(isinstance(p, GoalProposal) for p in proposals):
            raise TypeError("proposer must return GoalProposal objects")
        ids = [p.goal_id for p in proposals]
        if len(ids) != len(set(ids)):
            raise ValueError("duplicate goal_id in proposal batch")

        assessments = tuple(self._assess(p) for p in proposals)
        eligible = [a for a in assessments if a.eligible]
        # Stable tie-break prevents non-deterministic choice from model order.
        selected = sorted(
            eligible, key=lambda a: (-a.score, a.proposal.goal_id)
        )[0].proposal if eligible else None
        self._selected_id = selected.goal_id if selected else None
        return GoalDecision(
            owner_id=self.owner_id,
            selected=selected,
            assessments=assessments,
            created_at=datetime.now(timezone.utc).isoformat(),
        )

    def _assess(self, p: GoalProposal) -> GoalAssessment:
        score = 3 * p.expected_value + 2 * p.feasibility + p.learning_value
        if p.goal_id in self._outcomes and self._outcomes[p.goal_id].completed:
            reason = "already completed"
        else:
            approvals = []
            if p.external_effect:
                approvals.append("external action")
            if p.requires_new_access:
                approvals.append("new access")
            if p.estimated_spend_minor:
                approvals.append("spending")
            reason = (
                "planning permitted; independent authorization required for "
                + ", ".join(approvals)
                if approvals else "planning permitted; no external action authorized"
            )
        return GoalAssessment(
            proposal=p,
            eligible=(reason != "already completed"),
            reason=reason,
            score=score,
        )

    def record_outcome(self, goal_id: str, *, completed: bool, evidence: str) -> GoalOutcome:
        """Record verified progress against the last selected goal.

        The caller must independently verify evidence before reporting success.
        """
        if goal_id != self._selected_id:
            raise ValueError("only the current selected goal can be recorded")
        if type(completed) is not bool:
            raise ValueError("completed must be a boolean")
        if not isinstance(evidence, str) or not evidence.strip():
            raise ValueError("non-empty evidence is required")
        result = GoalOutcome(
            owner_id=self.owner_id,
            goal_id=goal_id,
            completed=completed,
            evidence=evidence.strip(),
        )
        self._outcomes[goal_id] = result
        self._selected_id = None
        return result
